def paired(base,new):
    assert set(base)==set(new), 'Both arms must have identical seed IDs'
    return [new[s]-base[s] for s in sorted(base)]

tests:
assert paired({2:0,1:1},{1:1,2:1})==[0,1], 'Match by seed, not insertion order'
assert paired({1:1},{1:0})==[-1], 'Keep negative effects'
try:
    paired({1:0},{2:1})
except AssertionError:
    pass
else:
    assert False, 'Mismatched identifiers must be rejected'

