from math import comb
def sign_p(positive,negative):
    n=positive+negative
    k=min(positive,negative)
    return min(1,2*sum(comb(n,i)*.5**n for i in range(k+1)))

from math import sqrt
def rms_d(model,human,scales):
    ds=[(m-h)/s for m,h,s in zip(model,human,scales)]
    return sqrt(sum(d*d for d in ds)/len(ds))

